            while True:
                x1, y1, z1 = randint(-1, 1), randint(-2, 2), randint(-1, 1)
                a1, b1, c1 = randint(1, 2), randint(1, 3), randint(1, 2)

                x2, y2, z2 = randint(1, 3), randint(1, 3), randint(1, 3)
                a2, b2, c2 = randint(1, 3), randint(1, 2), randint(1, 3)

                R_val = random.choice([3.5, 4.5, 5.5])

                # Kiểm tra điều kiện 2 đường thẳng chéo nhau (câu d)
                u1_cross_u2_x = b1*c2 - c1*b2
                u1_cross_u2_y = c1*a2 - a1*c2
                u1_cross_u2_z = a1*b2 - b1*a2
                AB_x = x2 - x1
                AB_y = y2 - y1
                AB_z = z2 - z1
                mix = u1_cross_u2_x * AB_x + u1_cross_u2_y * AB_y + u1_cross_u2_z * AB_z

                # Kiểm tra điều kiện cắt khí quyển (câu c)
                OA_cross_u1_x = y1*c1 - z1*b1
                OA_cross_u1_y = z1*a1 - x1*c1
                OA_cross_u1_z = x1*b1 - y1*a1
                num_sq = OA_cross_u1_x**2 + OA_cross_u1_y**2 + OA_cross_u1_z**2
                den_sq = a1**2 + b1**2 + c1**2

